export type CustomIconType = "preset" | "image" | "svg" | "emoji";

export type ButtonFontSize = "tiny" | "small" | "normal" | "medium" | "large";

export type ButtonIconSize = "small" | "normal" | "medium" | "large" | "xlarge";

export function getButtonFontSizeClass(fontSize?: ButtonFontSize): string | null {
  if (!fontSize) return null;
  switch (fontSize) {
    case "tiny":
      return "text-[9px]";
    case "small":
      return "text-[10px]";
    case "normal":
      return "text-[11px]";
    case "medium":
      return "text-xs";
    case "large":
      return "text-sm";
    default:
      return null;
  }
}

export function getButtonIconSizeClass(iconSize?: ButtonIconSize): string | null {
  if (!iconSize) return null;
  switch (iconSize) {
    case "small":
      return "w-3.5 h-3.5"; // 14px
    case "normal":
      return "w-4 h-4";     // 16px (standard ergonomic baseline)
    case "medium":
      return "w-4.5 h-4.5"; // 18px
    case "large":
      return "w-5 h-5";     // 20px
    case "xlarge":
      return "w-6 h-6";     // 24px
    default:
      return null;
  }
}

export type ComponentType = "button" | "page" | "tab" | "modal" | "panel" | "label";

export type ComponentPadding = "none" | "compact" | "normal" | "spacious" | "custom";

export type ComponentRadius = "none" | "sm" | "md" | "lg" | "xl" | "full" | "custom";

export type ComponentFontWeight = "normal" | "medium" | "semibold" | "bold" | "extrabold";

export type ComponentTextTransform = "none" | "uppercase" | "lowercase" | "capitalize";

