export function getComponentPaddingClass(padding?: ComponentPadding): string | null {
  if (!padding) return null;
  switch (padding) {
    case "none":
      return "p-0";
    case "compact":
      return "p-1.5 sm:p-2";
    case "normal":
      return "p-3 sm:p-4";
    case "spacious":
      return "p-5 sm:p-6";
    default:
      return null;
  }
}

export function getComponentRadiusClass(radius?: ComponentRadius): string | null {
  if (!radius) return null;
  switch (radius) {
    case "none":
      return "rounded-none";
    case "sm":
      return "rounded-md";
    case "md":
      return "rounded-xl";
    case "lg":
      return "rounded-2xl";
    case "xl":
      return "rounded-3xl";
    case "full":
      return "rounded-full";
    default:
      return null;
  }
}

export function getComponentFontWeightClass(weight?: ComponentFontWeight): string | null {
  if (!weight) return null;
  switch (weight) {
    case "normal":
      return "font-normal";
    case "medium":
      return "font-medium";
    case "semibold":
      return "font-semibold";
    case "bold":
      return "font-bold";
    case "extrabold":
      return "font-extrabold";
    default:
      return null;
  }
}

export interface ButtonCustomConfig {
  id: string;
  label?: string;
  iconName?: string;
  customIconType?: CustomIconType;
  customIconData?: string; // base64 data URI, SVG markup string, or emoji character
  hideText?: boolean; // individual zero-text mode
  hideIcon?: boolean; // individual text-only mode (display only text, no icon)
  hidden?: boolean; // hide component/button completely from render
  customTooltip?: string;
  accentColor?: string;
  textColor?: string; // custom text/label color
  backgroundColor?: string; // custom component background color
  borderColor?: string; // custom border color
  fontSize?: ButtonFontSize; // custom font size override
  iconSize?: ButtonIconSize; // custom icon size override
  // Component Registry enhancements:
  componentType?: ComponentType; // component classification (button, page, tab, modal, panel, label)
  fontFamily?: string; // custom typography font family
  fontWeight?: ComponentFontWeight; // font weight
  textTransform?: ComponentTextTransform; // uppercase, lowercase, capitalize, none
  letterSpacing?: string; // tracking-tight, tracking-wide, etc.
  padding?: ComponentPadding; // padding preset
  customPadding?: string; // custom CSS padding e.g. "8px 16px"
  cornerRadius?: ComponentRadius; // corner radius preset
  customCornerRadius?: string; // custom CSS border radius e.g. "12px"
}

export type GroupRuleMode = "inherit" | "icon_only" | "icon_and_text";

export interface GlobalCustomizationSettings {
  globalZeroTextMode: boolean; // when true, hide text on buttons unless explicitly overridden
  showRightClickHints: boolean;
  buttonOrder?: string[]; // custom drag-and-drop ordering of button IDs
  panelControlsOrder?: string[]; // custom ordering of front page panel controls bar
  headerItemsOrder?: string[]; // custom ordering of main top header navbar items
  groupSettings?: Record<string, GroupRuleMode>; // independent zero-text / icon-only rules per button group
  showCropDragHandles?: boolean; // drag and drop handles in Crop section (default: false)
  showAniPlayerDragHandles?: boolean; // drag and drop handles in AniPlayer (default: false)
  stripBackground?: string; // background color in storyboard strip view (default: "#000000")
  stripImageBackground?: string; // background color of strip image panel where image resides (default: "#000000")
  stripPanelBackground?: string; // background color of strip card panel container (default: "#000000")
  showSlotHeaders?: boolean; // show or hide the header bar with trashcans & actions in slot panels (default: true)
  showTopPanelButtons?: boolean; // show or hide top panel buttons across Control Deck and workspace (default: true)
  activeAiModel?: string; // Active AI model for Creative Studios and prompt generation (default: "models/gemini-3.8-flash")
  aiTemperature?: number; // AI generation creativity temperature (default: 0.7)
  aiMaxTokens?: number; // Max output tokens (default: 2048)
  globalFontSize?: ButtonFontSize; // Global button text size default ("tiny" | "small" | "normal" | "medium" | "large")
  globalIconSize?: ButtonIconSize; // Global button icon size default ("small" | "normal" | "medium" | "large" | "xlarge")
}

