export const BUTTON_DEFINITIONS: ButtonDefinition[] = (() => {
  const seen = new Set<string>();
  const combined: ButtonDefinition[] = [];
  for (const def of [
    ...BASE_BUTTON_DEFINITIONS,
    ...EXTENDED_BUTTON_DEFINITIONS,
    ...CATALOGUED_COMPONENTS,
    ...IBC_AUTOSCAN_DEFINITIONS,
  ]) {
    if (!seen.has(def.id)) {
      seen.add(def.id);
      combined.push(def);
    }
  }
  return combined;
})();

/**
 * Hardcoded permanent default button and label configurations.
 * Contains the complete preset definitions for all 607 buttons across the application.
 */
export const HARDCODED_DEFAULT_BUTTON_CONFIGS: Record<string, ButtonCustomConfig> = Object.freeze(
  (USER_DEFAULT_EXPORT_JSON.customConfigs || {}) as unknown as Record<string, ButtonCustomConfig>
);
